using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorTimelineOperations
{
    private readonly ModelDocumentOperations _models=new();
    public void rename_actor(RefCounted owner,Resource actor,string name){name=name.Trim();if(!Actors(owner).Contains(actor)||name.Length==0||name==actor.Get("display_name").AsString())return;History(owner,"Rename Actor","_set_name",new GArray{actor,name},"_set_name",new GArray{actor,actor.Get("display_name")});Changed(owner);}
    public void set_name(RefCounted owner,Resource actor,string name){actor.Set("display_name",name);actor.EmitChanged();Changed(owner);}
    public bool can_set_parent(RefCounted owner,string childId,string parentId)
    {
        var child=actor_for_id(owner,childId);if(child==null)return false;if(parentId.Length==0)return true;var parent=actor_for_id(owner,parentId);if(parentId==childId||parent==null||child.Get("section_id").AsString()!=parent.Get("section_id").AsString())return false;var visited=new HashSet<string>();while(parent!=null){string id=parent.Get("id").AsString();if(id==childId||!visited.Add(id))return false;parent=actor_for_id(owner,parent.Get("parent_id").AsString());}return true;
    }
    public Settings transform_values(Resource actor){var result=new Settings();var values=actor.Get("values").AsGodotDictionary();foreach(string name in new[]{"position","rotation","scale","model_basis_residual"}){StringName key=name;if(values.TryGetValue(key,out var value))result[key]=_data.copy_value(value);}return result;}
    public Transform3D local_transform(Resource actor)
    {
        if(actor.Get("type_id").AsString().EndsWith("_2d",StringComparison.Ordinal))return Transform3D.Identity;var position=_data.get_value(actor,"position",Vector3.Zero).AsVector3();var radians=_data.get_value(actor,"rotation",Vector3.Zero).AsVector3()*(Mathf.Pi/180);var scale=_data.get_value(actor,"scale",Vector3.One).AsVector3();var residual=Get(actor.Get("values").AsGodotDictionary(),"model_basis_residual",Basis.Identity).AsBasis();return new Transform3D(Basis.FromEuler(radians)*Basis.FromScale(scale)*residual,position);
    }
    public Transform3D world_transform_for(RefCounted owner,string id)=>world_transform_visited(owner,id,new Settings());
    public Transform3D world_transform_visited(RefCounted owner,string id,Settings visited){var actor=actor_for_id(owner,id);if(actor==null||visited.ContainsKey(id))return Transform3D.Identity;visited[id]=true;var local=local_transform(actor);string parent=actor.Get("parent_id").AsString();return parent.Length==0?local:world_transform_visited(owner,parent,visited)*local;}
    public Transform2D world_transform_2d_for(RefCounted owner,string id)=>world_transform_2d_visited(owner,id,new Settings());
    public Transform2D world_transform_2d_visited(RefCounted owner,string id,Settings visited){var actor=actor_for_id(owner,id);if(actor==null||!actor.Get("type_id").AsString().EndsWith("_2d",StringComparison.Ordinal)||visited.ContainsKey(id))return Transform2D.Identity;visited[id]=true;var local=new Transform2D((float)Mathf.DegToRad(_data.get_value(actor,"rotation",0.0).AsDouble()),_data.get_value(actor,"scale",Vector2.One).AsVector2(),0,_data.get_value(actor,"position",Vector2.Zero).AsVector2());return world_transform_2d_visited(owner,actor.Get("parent_id").AsString(),visited)*local;}
    public Settings values_for_preserved_world(RefCounted owner,Resource actor,string parentId)
    {
        var original=transform_values(actor);if(actor.Get("type_id").AsString().EndsWith("_2d",StringComparison.Ordinal)){var parent=world_transform_2d_for(owner,parentId);if(Math.Abs(parent.Determinant())<=.000001)return original;var local=parent.AffineInverse()*world_transform_2d_for(owner,actor.Get("id").AsString());return new Settings{[new StringName("position")]=local.Origin,[new StringName("rotation")]=Mathf.RadToDeg(local.Rotation),[new StringName("scale")]=local.Scale};}if(original.Count==0)return original;var world=world_transform_for(owner,actor.Get("id").AsString());var parentWorld=parentId.Length==0?Transform3D.Identity:world_transform_for(owner,parentId);if(Math.Abs(parentWorld.Basis.Determinant())<=.000001)return original;var relative=parentWorld.AffineInverse()*world;var values=actor.Get("values").AsGodotDictionary();if(values.ContainsKey(new StringName("model_basis_residual")))return _models.transform_values(relative);var scale=relative.Basis.Scale;var radians=relative.Basis.Orthonormalized().GetEuler();if(values.ContainsKey(new StringName("position")))original[new StringName("position")]=relative.Origin;if(values.ContainsKey(new StringName("rotation")))original[new StringName("rotation")]=radians*(180/Mathf.Pi);if(values.ContainsKey(new StringName("scale")))original[new StringName("scale")]=scale;return original;
    }
    public void apply_parent_state_silent(Resource actor,string parentId,Settings values){actor.Set("parent_id",parentId);var stored=actor.Get("values").AsGodotDictionary();foreach(var entry in values)stored[entry.Key]=_data.copy_value(entry.Value);actor.EmitChanged();}
    public void set_parent_state(RefCounted owner,Resource actor,string parent,Settings values){apply_parent_state_silent(actor,parent,values);Changed(owner);}
    public void set_parent(RefCounted owner,string childId,string parentId,bool preserve)
    {
        var child=actor_for_id(owner,childId);if(child==null||child.Get("parent_id").AsString()==parentId||!can_set_parent(owner,childId,parentId))return;string previous=child.Get("parent_id").AsString();var before=transform_values(child);var after=preserve?values_for_preserved_world(owner,child,parentId):before;History(owner,parentId.Length>0?"Parent Actor":"Unparent Actor","_set_parent_state",new GArray{child,parentId,after},"_set_parent_state",new GArray{child,previous,before});Changed(owner);
    }
    public void parent_many(RefCounted owner,GArray ids,string parentId)
    {
        var parent=actor_for_id(owner,parentId);if(parent==null)return;var lookup=new Settings();foreach(var value in ids){string id=value.AsString();var child=actor_for_id(owner,id);if(id!=parentId&&child!=null&&child.Get("section_id").AsString()==parent.Get("section_id").AsString())lookup[id]=true;}if(lookup.Count==0)return;var states=new Settings();var ancestor=actor_for_id(owner,parent.Get("parent_id").AsString());if(ancestor!=null&&lookup.ContainsKey(ancestor.Get("id"))){var visited=new HashSet<string>();while(ancestor!=null&&lookup.ContainsKey(ancestor.Get("id"))){if(!visited.Add(ancestor.Get("id").AsString()))return;ancestor=actor_for_id(owner,ancestor.Get("parent_id").AsString());}string external=ancestor?.Get("id").AsString()??"";states[parent.Get("id")]=new Settings{["old_parent"]=parent.Get("parent_id"),["old_values"]=transform_values(parent),["new_parent"]=external,["new_values"]=values_for_preserved_world(owner,parent,external)};}foreach(var id in lookup.Keys){var child=actor_for_id(owner,id.AsString())!;states[id]=new Settings{["old_parent"]=child.Get("parent_id"),["old_values"]=transform_values(child),["new_parent"]=parentId,["new_values"]=values_for_preserved_world(owner,child,parentId)};}commit_parent_states(owner,states,"Parent Actors");
    }
    public void unparent_many(RefCounted owner,GArray ids){var states=new Settings();foreach(var value in ids){var actor=actor_for_id(owner,value.AsString());if(actor!=null&&actor.Get("parent_id").AsString().Length>0)states[value]=new Settings{["old_parent"]=actor.Get("parent_id"),["old_values"]=transform_values(actor),["new_parent"]="",["new_values"]=values_for_preserved_world(owner,actor,"")};}commit_parent_states(owner,states,"Unparent Actors");}
    public void commit_parent_states(RefCounted owner,Settings states,string label){if(states.Count==0)return;History(owner,label,"_apply_parent_states",new GArray{states,true},"_apply_parent_states",new GArray{states,false});Changed(owner);}
    public void apply_parent_states(RefCounted owner,Settings states,bool useNew){foreach(var entry in states){var actor=actor_for_id(owner,entry.Key.AsString());if(actor==null)continue;var state=entry.Value.AsGodotDictionary();apply_parent_state_silent(actor,state[useNew?"new_parent":"old_parent"].AsString(),state[useNew?"new_values":"old_values"].AsGodotDictionary());}Changed(owner);}
    public void trim_clip(RefCounted owner,string id,double start,double duration)
    {
        int index=index_of(owner,id);if(index<0||!double.IsFinite(start)||!double.IsFinite(duration))return;var clip=Clips(owner)[index].As<Resource>();start=Math.Max(0,start);duration=Math.Max(minimum_duration(owner,clip),duration);var linked=linked_clip_ids(owner,new GArray{id});if(linked.Count>1){double left=start-clip.Get("start_time").AsDouble(),right=start+duration-clip.Get("start_time").AsDouble()-clip.Get("duration").AsDouble();var states=new Settings();foreach(string childId in linked){var child=Clips(owner)[index_of(owner,childId)].As<Resource>();states[childId]=new Settings{["start"]=child.Get("start_time").AsDouble()+left,["duration"]=child.Get("duration").AsDouble()+right-left,["offset"]=child.Get("source_offset").AsDouble()+left*child.Get("playback_speed").AsDouble(),["layer"]=child.Get("layer")};}commit_clip_states(owner,states,"Trim Linked Actors",id);return;}if(!can_place(owner,id,start,duration,clip.Get("layer").AsInt32()))return;if(Mathf.IsEqualApprox(start,clip.Get("start_time").AsDouble())&&Mathf.IsEqualApprox(duration,clip.Get("duration").AsDouble()))return;double offset=clip.Get("source_offset").AsDouble()+(start-clip.Get("start_time").AsDouble())*clip.Get("playback_speed").AsDouble();if(!_audio.valid(Actors(owner)[index].As<Resource>(),clip,duration,offset))return;History(owner,"Trim Actor","_set_timing",new GArray{clip,start,duration,offset},"_set_timing",new GArray{clip,clip.Get("start_time"),clip.Get("duration"),clip.Get("source_offset")});Changed(owner);
    }
    public void set_timing(RefCounted owner,Resource clip,double start,double duration,double offset){clip.Set("start_time",start);clip.Set("duration",duration);clip.Set("source_offset",offset);clip.EmitChanged();make_primary(owner,clip.Get("id").AsString());owner.Set("selected_layer",clip.Get("layer"));Changed(owner);}
}
